import{_ as t}from"./chunks/protocol.BCHVaPua.js";import{_ as a}from"./chunks/formats.Bqa4Tjr1.js";import{_ as r,o as i,c as n,a2 as s}from"./chunks/framework.BefGvJmu.js";const o="/pai-website/assets/diagrams/exchange.svg",g=JSON.parse('{"title":"PAI architecture","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),d={name:"guide/architecture.md"};function c(l,e,p,h,u,m){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="pai-architecture" tabindex="-1">PAI architecture <a class="header-anchor" href="#pai-architecture" aria-label="Permalink to &quot;PAI architecture&quot;">​</a></h1><p>This document describes the current content profile and its reference implementation. It is informative. <a href="/pai-website/spec/service.html">SERVICE.md</a>, <a href="/pai-website/spec/format.html">FORMAT.md</a>, and <a href="/pai-website/spec/hash.html">HASH.md</a> define protocol and file requirements.</p><h2 id="client-and-server-interface" tabindex="-1">Client and server interface <a class="header-anchor" href="#client-and-server-interface" aria-label="Permalink to &quot;Client and server interface&quot;">​</a></h2><p>A host application uses a PAI client to exchange content with a selected service. The same service accepts publication requests and exposes published resources to other clients. The service provider operates the server and supplies its account system, storage, and product interface.</p><p><img src="'+t+'" alt="Publisher and reader applications use PAI clients to exchange content with one selected service. The server checks publication ownership and retains versioned content and original files."></p><p>The content profile specifies service discovery, supported upload formats, authenticated writes, published resources, snapshots, structured-content responses, file downloads, and source URLs. A platform integrates those operations with its own services. Follo is one potential operator of such a deployment.</p><p>The reference server uses a configured set of publisher credentials and filesystem snapshots. A different implementation can use an existing account system and database while providing the same observable protocol behavior. <a href="/pai-website/guide/server.html">Server integration</a> describes that implementation contract.</p><h2 id="publication-and-retrieval" tabindex="-1">Publication and retrieval <a class="header-anchor" href="#publication-and-retrieval" aria-label="Permalink to &quot;Publication and retrieval&quot;">​</a></h2><p>The client obtains endpoint URLs from the service descriptor. Uploads carry the original ZIP or HTML file bytes. The server validates the file and determines the publisher from the credential.</p><p><img src="'+o+'" alt="Publisher discovery and authenticated upload are followed by reader discovery, resource selection, versioned content retrieval, and optional original-file download."></p><p>Ordinary text reads use structured content. Original-image extraction reads the selected version&#39;s file. Block source URLs identify a particular publication version so a later update retains the earlier source.</p><p>An equivalent publication retry returns <code>200</code> and its stored snapshot. Updating a resource uses its declared <code>updateUrl</code> and requires the owning publisher&#39;s credential. A new document revision creates the next publication version. The document&#39;s edit counter and the server&#39;s publication counter have separate meanings; <a href="/pai-website/spec/service.html">service behavior</a> defines the retry and conflict rules.</p><h2 id="shared-document-model" tabindex="-1">Shared document model <a class="header-anchor" href="#shared-document-model" aria-label="Permalink to &quot;Shared document model&quot;">​</a></h2><p>The content model contains document identity and revision, Markdown content blocks, ordered layout rows, and image assets. A block references each image by asset ID. Layout rows supply reading order and one-, two-, or three-column placement. The renderer chooses fonts, spacing, and responsive breakpoints while preserving the defined content order.</p><p><img src="'+a+'" alt="A shared document model is stored as .pai with document.json and original assets, or exported as .pai.html with embedded data and a browser rendering and editing runtime."></p><p>Packaging-only conversion preserves all document fields and original image bytes, including unused assets. It changes their storage representation: ZIP entries use asset paths; HTML embeds Base64 data. <a href="/pai-website/spec/hash.html">Content hashing</a> computes a common digest across these forms.</p><p>A <code>.pai</code> file contains the document and original images. Compatible tools supply the parser, renderer, and editor. A complete <code>.pai.html</code> export includes that runtime so a supported browser can open and edit it offline. Data readers extract the JSON without executing the embedded program. The reference service renders uploaded content with its own runtime.</p><p>A service can also retain the same content in a database and asset store. The interchange format governs exported and transferred representations; it does not prescribe the database schema.</p><h2 id="reference-implementation" tabindex="-1">Reference implementation <a class="header-anchor" href="#reference-implementation" aria-label="Permalink to &quot;Reference implementation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td>Content specification</td><td><code>spec/</code></td><td>Required data, file, and service behavior</td></tr><tr><td>File module</td><td><code>content/src/</code></td><td>Parsing, validation, content editing, conversion, and image access</td></tr><tr><td>Browser editor</td><td><code>content/src/</code></td><td>Direct editing, layout, local save, and standalone export</td></tr><tr><td>File CLI</td><td><code>content/cli.mjs</code></td><td>File inspection, patches, conversion, hashing, and image extraction</td></tr><tr><td>Publication client</td><td><code>src/publication-client.ts</code>, <code>src/publish.ts</code></td><td>Discovery, authenticated writes, and response validation</td></tr><tr><td>Retrieval client</td><td><code>src/content-client.ts</code>, <code>src/read.ts</code></td><td>Public content, history, source links, and original-image extraction</td></tr><tr><td>Reference server</td><td><code>src/provider.ts</code>, <code>src/documents.ts</code></td><td>Request handling, publisher authorization, and snapshots</td></tr><tr><td>Service checker</td><td><code>src/check-service.ts</code></td><td>Checks through a service&#39;s advertised interfaces</td></tr></tbody></table><p>Node file tools and the browser editor share the parser and validation rules. Browser saving produces a local download. Publishing that saved document is a separate client operation. The protocol does not require a particular editor UI.</p><p>Testing instructions, Harness tasks, browser acceptance, and development reports are kept in <a href="https://github.com/JacenDu/pai-protocol/blob/main/development/README.md" target="_blank" rel="noreferrer"><code>development/</code></a>. The public integration guides are <a href="/pai-website/guide/client.html">Client integration</a> and <a href="/pai-website/guide/server.html">Server integration</a>.</p><h2 id="planned-extensions" tabindex="-1">Planned extensions <a class="header-anchor" href="#planned-extensions" aria-label="Permalink to &quot;Planned extensions&quot;">​</a></h2><p>Open retrieval will build on publication versions, block IDs, asset IDs, and source URLs. The next design work concerns queries, returned excerpts, and how clients identify the material used in an answer. The current content profile provides catalogue and content reads; it has no vector-search or query endpoint.</p><p>Hosted-agent interactions will cover a service-operated agent acting within a user&#39;s authorized scope, using the material and preferences that user makes available. That work needs explicit authorization and request-result semantics. It remains planned work, with no capability or message schema in the current content draft.</p>',25)])])}const w=r(d,[["render",c]]);export{g as __pageData,w as default};
